<script>
import {data,profile,updateData,notify,download} from '../lib/store.js';
import {FINANCE_GROUPS,FINANCE_RESOURCES,accountPage,ACCOUNT_LINKS,ledger,accountSummary,money,aidYears,awards,awardTotals,aidYearLabel,installments,validDate} from '../lib/student-account.js';
import Icon from '../lib/components/Icon.svelte';
let {route}=$props();let view=$derived(route.split('/')[1]??'overview');let page=$derived(accountPage(route));
let summary=$derived(accountSummary($profile));let year=$state(2027);let rows=$derived(awards($profile,year));let totals=$derived(awardTotals($profile,year,year===2027?$data.finance.decisions:{}));
let decisions=$state({...$data.finance.decisions});let agreement=$state(false);let selectedTerm=$state('Fall 2026');let showStatus=$state(false);
let provider=$state($data.finance.waiver?.provider??'');let start=$state($data.finance.waiver?.start??'');let end=$state($data.finance.waiver?.end??'');let waiverTerm=$state($data.finance.waiver?.term??'Fall 2026');let error=$state('');
function saveFinance(patch,message){updateData({...$data,finance:{...$data.finance,...patch}});notify(message);}
function saveAid(e){e.preventDefault();saveFinance({decisions:{...decisions}},'Award decision draft saved in this browser.');}
function saveWaiver(e){e.preventDefault();if(!provider.trim()||!validDate(start)||!validDate(end)||start>end){error='Enter a provider and valid coverage dates, with the end on or after the start.';return;}error='';saveFinance({waiver:{term:waiverTerm,provider:provider.trim(),start,end,status:'Draft'}},'Waiver checklist saved as a local draft.');}
function exportBill(){download('catalyst-sample-bill.csv','Sample account activity — not an official bill\nDate,Description,Amount USD\n'+ledger($profile).map(r=>`${r.date},${r.description},${(r.cents/100).toFixed(2)}`).join('\n')+`\n,Sample balance,${(summary.balance/100).toFixed(2)}`,'text/csv');}
const terms=Array.from({length:14},(_,i)=>{const year=2026-Math.floor(i/3);const season=['Fall','Summer','Spring'][i%3];return `${season} ${year}`;});
</script>
{#if view==='overview'}
<div class="page-heading"><div><p class="eyebrow">Your financial home</p><h1>My Finances</h1><p>Your account, financial aid, and insurance resources in one place.</p></div><span class="badge neutral">Sample amounts</span></div>
<div class="account-overview-grid"><section class="panel academic-overview-card"><div class="academic-panel-title"><Icon name="wallet"/><h2>Account Summary</h2></div><div class="padded academic-copy"><span class="eyebrow">Sample balance</span><div class="account-balance">{money(summary.balance)}</div><dl class="academic-definition"><div><dt>Due Now</dt><dd>{money(summary.dueNow)}</dd></div><div><dt>Future Due</dt><dd>{money(summary.futureDue)}</dd></div><div><dt>Last Payment</dt><dd>{money(-summary.lastPayment.cents)}<small class="muted block">Sample payment · {summary.lastPayment.date}</small></dd></div></dl><div class="account-actions">{#each [['pending-aid','View Pending Financial Aid'],['bill','View Itemized Bill'],['inquiry','Account Inquiry'],['payment','Make a Payment']] as [id,label]}<a href={`#/finances/${id}`} class={id==='payment'?'button primary':'button secondary'}>{label}<Icon name="arrow" size={16}/></a>{/each}</div><p class="fine-print">Illustrative records only. Verify your real account balance in official Catalyst.</p></div></section>
<div class="account-stack"><section class="panel academic-overview-card"><div class="academic-panel-title"><Icon name="star"/><h2>Financial Aid Awards</h2></div><div class="padded academic-copy"><div class="section-heading"><h3>{aidYearLabel(2027)}</h3><span class="badge neutral">Sample aid</span></div><dl class="academic-definition"><div><dt>Offered</dt><dd>{money(totals.offered)}</dd></div><div><dt>Accepted in local draft</dt><dd>{money(totals.accepted)}</dd></div></dl>{#each awards($profile,2027) as award}<div class="account-award" class:declined={$data.finance.decisions[award.id]==='Declined'}><Icon name={$data.finance.decisions[award.id]==='Declined'?'close':'check'} size={18}/><div><strong>{award.name}</strong><small>{money(award.cents)} · {$data.finance.decisions[award.id]??'Accepted'} in sample draft</small></div></div>{/each}<a class="button primary spaced" href="#/finances/accept-decline">Accept / Decline Awards<Icon name="arrow" size={16}/></a></div></section><section class="panel academic-overview-card"><div class="academic-panel-title"><Icon name="shield"/><h2>Tuition Guarantee – Cohort Details</h2></div><div class="padded academic-copy"><p>Find the official tuition guarantee information for your entering cohort and campus.</p><a class="button secondary" href="#/finances/cohort">View Current Cohort Details<Icon name="arrow" size={16}/></a></div></section></div></div>
<div class="account-directory spaced">{#each FINANCE_GROUPS as group}<section class="panel padded"><div class="section-heading"><h2>{group.label}</h2><Icon name={group.icon}/></div>{#each group.items as item}<a class="academic-directory-link" href={item.href}><span>{item.label}</span><Icon name="arrow" size={15}/></a>{/each}</section>{/each}</div>
{:else if page}
<nav class="academic-breadcrumb" aria-label="Finance breadcrumb"><a href="#/finances">My Finances</a><Icon name="chevron" size={12}/><span>{page.group}</span></nav><div class="page-heading"><div><p class="eyebrow">{page.group}</p><h1>{page.label}</h1><p>{page.description}</p></div></div>
{#if FINANCE_RESOURCES[view]}{@const resource=FINANCE_RESOURCES[view]}<section class="panel padded academic-copy account-resource"><span class="tile-icon"><Icon name={view==='insurance-card'?'shield':'external'} size={25}/></span><h2>{page.label}</h2><p>{resource.text}</p><a class="button primary" href={resource.url} target="_blank" rel="noreferrer">{resource.label}<Icon name="external" size={16}/></a><p class="fine-print">Opens the official resource in a new tab.</p>{#if view==='payment'}<div class="notice"><Icon name="info"/><p>Sample balance: {money(summary.balance)}. No payment is due through this prototype.</p></div>{/if}{#if view==='insurance-card'}<a class="text-link spaced" href="#/finances/waiver-status">Review sample waiver status <Icon name="arrow" size={15}/></a>{/if}</section>
{:else if ['bill','inquiry'].includes(view)}<section class="panel padded"><div class="section-heading"><div><h2>{view==='bill'?'Itemized sample bill':'Sample account activity'}</h2><p class="muted small">Fall 2026 · USD · {$profile.studentId}</p></div><button class="button secondary" onclick={exportBill}>Download sample CSV<Icon name="download" size={16}/></button></div><div class="table-scroll"><table class="academic-table"><thead><tr><th>Date</th><th>Description</th><th>Type</th><th>Amount</th></tr></thead><tbody>{#each ledger($profile) as row}<tr><td>{row.date}</td><td>{row.description}</td><td>{row.kind}</td><td>{money(row.cents)}</td></tr>{/each}</tbody><tfoot><tr><th colspan="3">Sample balance</th><td><strong>{money(summary.balance)}</strong></td></tr></tfoot></table></div><p class="fine-print">Local award decision drafts do not change posted account activity. This is not an official statement.</p><div class="button-row"><a class="button primary" href="#/finances/payment">Payment instructions<Icon name="arrow" size={16}/></a><a class="button secondary" href="#/finances/tax">1098-T Tax Form</a></div></section>
{:else if ['financial-aid','accept-decline','pending-aid'].includes(view)}<section class="panel padded"><div class="academic-controls"><label>Aid year<select bind:value={year} onchange={()=>decisions={...$data.finance.decisions}}>{#each aidYears($profile) as y}<option value={y}>{aidYearLabel(y)}</option>{/each}</select></label><span class="badge neutral">Synthetic awards</span></div>{#if rows.length}<div class="metrics-grid three"><div class="metric"><span>Offered</span><strong>{money(totals.offered)}</strong></div><div class="metric"><span>Accepted in saved draft</span><strong>{money(totals.accepted)}</strong></div><div class="metric"><span>Aid year</span><strong>{aidYearLabel(year)}</strong></div></div><form onsubmit={saveAid}><div class="table-scroll"><table class="academic-table"><thead><tr><th>Award</th><th>Offered</th><th>{view==='pending-aid'?'Disbursement status':'Decision'}</th></tr></thead><tbody>{#each rows as award}<tr><td>{award.name}</td><td>{money(award.cents)}</td><td>{#if view==='accept-decline'&&year===2027}<select aria-label={`Decision for ${award.name}`} id={`award-${award.id}`} value={decisions[award.id]??'Accepted'} onchange={e=>decisions={...decisions,[award.id]:e.currentTarget.value}}><option>Accepted</option><option>Declined</option></select>{:else if view==='pending-aid'}Illustrative · not disbursed{:else}{year===2027?$data.finance.decisions[award.id]??'Accepted':'Accepted (sample archive)'}{/if}</td></tr>{/each}</tbody></table></div>{#if view==='accept-decline'&&year===2027}<div class="button-row spaced"><button class="button primary" type="submit">Save decision draft</button><button class="button secondary" type="button" onclick={()=>decisions={...$data.finance.decisions}}>Discard unsaved changes</button></div>{/if}</form><p class="fine-print">{view==='pending-aid'?'Anticipated awards are shown separately from the posted credits on the sample bill.':'These decisions are local practice drafts. Saving does not accept, decline, or disburse real aid.'} Older years are read-only sample archives.</p>{:else}<div class="empty-state"><Icon name="file" size={30}/><h2>No financial aid data available.</h2><p>There are no sample awards for {aidYearLabel(year)}. Choose another aid year.</p></div>{/if}<a class="text-link spaced" href={ACCOUNT_LINKS.help} target="_blank" rel="noreferrer">Official aid instructions<Icon name="external" size={15}/></a></section>
{:else if view==='direct-deposit'}<section class="panel padded academic-copy"><h2>Direct Deposit Summary</h2><p>Sample account information is masked. Follow the university’s instructions to manage real bank details.</p><div class="table-scroll"><table class="academic-table"><thead><tr><th>Account</th><th>Distribution Type</th><th>Amount / Percent</th><th>Priority</th></tr></thead><tbody><tr><td>Sample account · •••• 4242</td><td>Balance</td><td>Remaining balance</td><td>1</td></tr></tbody></table></div><p class="fine-print">Fictional account · USD. No banking system is connected.</p><div class="button-row"><a class="button primary" href={ACCOUNT_LINKS.deposit} target="_blank" rel="noreferrer">Official enrollment & Employee Self-Service instructions<Icon name="external" size={16}/></a></div><div class="account-quicklinks"><a href="#/finances/inquiry">Account Inquiry</a><a href="#/finances/tax">1098-T Tax Form</a><a href="#/finances/permissions">Student Permission</a><a href="#/finances/bank-accounts">Bank Accounts</a></div></section>
{:else if view==='refund-appeal'}<section class="panel padded academic-copy"><span class="tile-icon"><Icon name="info"/></span><h2>No eligible sample terms</h2><p>This demo account has no terms eligible for a tuition refund appeal. Your real eligibility must be checked in official Catalyst.</p><div class="button-row"><a class="button primary" href="#/finances">OK, return to My Finances</a><a class="button secondary" href={ACCOUNT_LINKS.bursar} target="_blank" rel="noreferrer">Contact the Bursar<Icon name="external" size={16}/></a></div></section>
{:else if view==='payment-plan'}<section class="panel padded academic-copy"><h2>Three-installment planning example</h2><p>{summary.balance===0?'This sample account has no remaining balance. A $1,200 example below lets you explore the layout.':'This example divides the sample balance into three installments.'} Dates, fees, and eligibility are confirmed through the official service.</p><div class="scenario-columns">{#each installments(summary.balance||120000) as amount,i}<div class="panel padded"><span class="eyebrow">Installment {i+1}</span><h2>{money(amount)}</h2><span class="muted small">Illustrative amount</span></div>{/each}</div><div class="button-row"><button class="button secondary" onclick={()=>saveFinance({planSaved:!$data.finance.planSaved},$data.finance.planSaved?'Planning example removed.':'Planning example saved locally.')}>{$data.finance.planSaved?'Remove saved example':'Save planning example'}</button><a class="button primary" href={ACCOUNT_LINKS.plan} target="_blank" rel="noreferrer">Official payment plan enrollment<Icon name="external" size={16}/></a></div><p class="fine-print">{$data.finance.planSaved?'Saved locally · ':''}Saving this example does not enroll you in a payment plan.</p></section>
{:else if view==='permissions'}<section class="panel padded academic-copy"><h2>Student Permissions</h2><div class="table-scroll"><table class="academic-table"><thead><tr><th>Permission Form</th><th>Description</th><th>Status</th></tr></thead><tbody><tr><td>TITLEIV</td><td>Sample permission relating to the application of federal aid to eligible charges.</td><td>Example only</td></tr></tbody></table></div><button class="button secondary spaced" aria-expanded={agreement} onclick={()=>agreement=!agreement}>{agreement?'Hide':'Display'} Student Agreement</button>{#if agreement}<div class="notice spaced"><Icon name="info"/><p>This example is not a binding agreement. Read the complete agreement presented in official Catalyst before making any authorization.</p></div><a class="text-link spaced" href={ACCOUNT_LINKS.catalyst} target="_blank" rel="noreferrer">Open official Catalyst<Icon name="external" size={16}/></a>{/if}</section>
{:else if view==='waiver-status'}<section class="panel padded academic-copy"><h2>Select a term</h2><form class="academic-form" onsubmit={e=>{e.preventDefault();showStatus=true;}}><label>Health insurance term<select bind:value={selectedTerm} onchange={()=>showStatus=false}>{#each terms as term}<option>{term}</option>{/each}</select></label><button class="button primary">Continue</button></form>{#if showStatus}<div class="notice spaced" role="status"><Icon name="info"/><p><strong>{selectedTerm}</strong><br/>{$data.finance.waiver?.term===selectedTerm?'Local checklist saved · draft only.':'No official waiver record is connected.'} This screen cannot establish insurance coverage or waiver approval.</p></div>{/if}<a class="text-link spaced" href="#/finances/waiver-update">Prepare waiver update checklist<Icon name="arrow" size={15}/></a><a class="text-link spaced" href={ACCOUNT_LINKS.insurance} target="_blank" rel="noreferrer">Official waiver information<Icon name="external" size={15}/></a></section>
{:else if view==='waiver-update'}<section class="panel padded academic-copy"><h2>Prepare your waiver checklist</h2><p>Use fictional examples to explore this form. Save a checklist here, then complete any actual waiver through official university services.</p><form class="academic-form" onsubmit={saveWaiver}><label>Term<select bind:value={waiverTerm}>{#each ['Fall 2026','Spring 2027','Summer 2027'] as term}<option>{term}</option>{/each}</select></label><label>Example provider name<input required maxlength="120" placeholder="Example Health Plan" bind:value={provider}/></label><div class="form-two-columns"><label>Coverage start<input required type="date" bind:value={start}/></label><label>Coverage end<input required type="date" bind:value={end}/></label></div>{#if error}<p class="form-error" role="alert">{error}</p>{/if}<button class="button primary">Save checklist draft</button></form>{#if $data.finance.waiver}<p class="fine-print">Saved draft · {$data.finance.waiver.term} · {$data.finance.waiver.provider}. Not submitted or approved.</p>{/if}<a class="text-link spaced" href={ACCOUNT_LINKS.insurance} target="_blank" rel="noreferrer">Complete your official waiver<Icon name="external" size={16}/></a></section>{/if}
<a class="text-link spaced" href="#/finances"><Icon name="arrow" size={15}/>Back to My Finances</a>
{:else}<section class="panel empty-state"><h1>Finance page not found.</h1><a class="button primary" href="#/finances">My Finances</a></section>{/if}
